Edit a file. Text: exact old_string/new_string (whitespace-sensitive; re-indent retry in brace languages), insert prepend/append, replace_all, or edits[] applied atomically. Markdown: heading-addressed section edits, edits[] of heading items, frontmatter {set, delete} — one atomic write.

exec tool declaration:
```ts
declare const tools: { mcp__codescout__edit_file(args: {
  // Markdown only, with `heading` (not with edits[]); omit for old_string/new_string text edits. 'replace' OVERWRITES the body (heading kept); 'edit' = old_string/new_string inside it; 'insert_before'/'insert_after' add a sibling section; 'remove' deletes it.
  action?: "replace" | "insert_before" | "insert_after" | "remove" | "edit";
  // Markdown only, for action='insert_after': where to insert. 'end-of-section' (default) or 'after-heading-line'.
  at?: "end-of-section" | "after-heading-line";
  // Markdown only: the section's new body text for replace/insert actions (heading preserved on replace; insert_before's body must start with its own heading line). `body` not `content`: a text parameter is `body` when the tool also takes a contrasting sibling — here `frontmatter`. `content` is accepted as an alias.
  body?: string;
  // Batch mode: array of edit operations applied atomically. Top-level new_string not used. Every item must use the same grammar (text or markdown).
  edits?: Array<{
  action?: "replace" | "insert_before" | "insert_after" | "remove" | "edit";
  at?: "end-of-section" | "after-heading-line";
  // Markdown grammar: this entry's new section body. Stays `content`, not `body` — an item has no `frontmatter` sibling, so the tool-level rule does not reach it.
  content?: string;
  // Markdown grammar: target section heading, or "^" for the PREAMBLE (action="edit" only).
  heading?: string;
  include_subsections?: boolean;
  // Text grammar: replacement text.
  new_string?: string;
  occurrence?: number;
  // Text grammar: exact text to find.
  old_string?: string;
  replace_all?: boolean;
}>;
  // Markdown only: bypass the body-shrink guard. Required when the write would cut the file by >50% in bytes or lines.
  force?: boolean;
  // Markdown only: mutate the YAML frontmatter block at the start of the file. Flat keys only. Combinable atomically with `edits` or `heading`+`action` in the same call. Example: `{set: {status: "fixed"}, delete: ["legacy_field"]}`.
  frontmatter?: {
  // Keys to remove from the block. Missing keys are silently ignored (idempotent).
  delete?: Array<string>;
  // Key → value pairs to set. Existing keys are updated in place; new keys are appended.
  set?: { [key: string]: unknown; };
};
  // Markdown only: target section heading (fuzzy matched). Required unless using edits[] batch mode. "^" targets the PREAMBLE (text before the first heading), action="edit" only.
  heading?: string;
  // Markdown only, for action='replace': opt in to consuming nested sub-headings.
  include_subsections?: boolean;
  // Insert at file start/end (old_string not required).
  insert?: "prepend" | "append";
  // Replacement text (empty string = delete). Required for single-edit and insert modes.
  new_string?: string;
  // Markdown only: 1-indexed selector when `heading` matches several sections.
  occurrence?: number;
  // Exact text to find (whitespace-sensitive). Required unless insert or edits is set.
  old_string?: string;
  // File path
  path?: string;
  // Replace all occurrences.
  replace_all?: boolean;
  // Absolute workspace path to resolve this call against; omit for the active project. For concurrent subagents in different workspaces.
  workspace?: string;
}): Promise<CallToolResult>; };
```

