Persistent project memory. Topic-based: read/write/list/delete/refresh_anchors with path-like keys. Semantic: remember/recall/forget with bucket classification and meaning-based search.

exec tool declaration:
```ts
declare const tools: { mcp__codescout__memory(args: {
  // Operation to perform; refresh_anchors re-hashes anchors only.
  action: "read" | "write" | "list" | "delete" | "remember" | "recall" | "forget" | "refresh_anchors";
  // For remember (always specify) or recall (optional filter).
  bucket?: "code" | "system" | "preferences" | "unstructured";
  // For write or remember.
  content?: string;
  // For write: bypass the shrink guard. Required when the write would replace an existing topic with less than half its bytes. `write` REPLACES wholesale — it never appends — so a partial document is data loss, not an update.
  force?: boolean;
  // For forget. UUID string from a recall result.
  id?: string;
  // For list: include private topics.
  include_private?: boolean;
  // For recall. Max results (default 5).
  limit?: number;
  // Use gitignored private store.
  private?: boolean;
  // Scope to a workspace project ID. Default: focused project.
  project_id?: string;
  // For recall. Search query.
  query?: string;
  // For read. Return only the listed sections (case-insensitive). Sections are the memory's shallowest heading level below the title — `##` in most memories, `###` in some; deeper headings come along as body. E.g. ["Rust", "MCP Binary Symlink"]. Omit to return full content.
  sections?: Array<string>;
  // For remember. Short label (auto-extracted if omitted).
  title?: string;
  // For read/write/delete/refresh_anchors. Path-like key, e.g. 'architecture'.
  topic?: string;
  // Absolute workspace path to resolve this call against; omit for the active project. For concurrent subagents in different workspaces.
  workspace?: string;
}): Promise<CallToolResult>; };
